"""GIFTORA: сервер + бот в одном файле. Раздаёт index.html, хранит данные, проверяет Telegram, принимает Stars."""
import random, aiohttp, re, base64, asyncio, hashlib, hmac, json, os, sqlite3, time
from urllib.parse import parse_qsl
from aiohttp import web
from aiogram import Bot, Dispatcher, F
from aiogram.filters import Command
from aiogram.types import (BufferedInputFile, CallbackQuery, Message, WebAppInfo, InlineKeyboardMarkup, InlineKeyboardButton,
                           LabeledPrice, PreCheckoutQuery, MenuButtonWebApp)

PAGE = base64.b64decode("").decode()  # страница приложения встроена в этот файл
BANNER = base64.b64decode("")  # рекламный баннер для /start
TOKEN = os.environ["BOT_TOKEN"]
CHANNEL = os.environ.get("CHANNEL_URL", "")
SUPPORT = os.environ.get("SUPPORT", "")
URL = os.environ["WEBAPP_URL"]
ADMIN_ID = int(os.environ.get("ADMIN_ID", "0"))
ADMINS = {a.strip().lower() for a in os.environ.get("ADMINS", "laymik123").split(",")}
bot, dp, BOTNAME = Bot(TOKEN), Dispatcher(), ""

db = sqlite3.connect(os.environ.get("DB_PATH", "giftora.db"))
db.execute("create table if not exists kv(k text primary key, v text)")
row = db.execute("select v from kv where k='s'").fetchone()
st = json.loads(row[0]) if row else {"users": {}, "items": [], "favs": {}, "deals": [],
                                      "media": [], "tickets": [], "bal": {}, "nid": 1}
st.setdefault("admins", []); st.setdefault("fee", 0); st.setdefault("swaps", []); st.setdefault("pay", []); st.setdefault("subs", {}); st.setdefault("ev", [])
def save():
    db.execute("replace into kv values('s',?)", (json.dumps(st),)); db.commit()

BDS = ("Чёрный", "Синий", "Красный", "Зелёный", "Фиолетовый", "Золотой")
class Err(Exception): pass

def tell(uid, text):
    async def go():
        try: await bot.send_message(uid, text)
        except Exception: pass
    if uid: asyncio.get_running_loop().create_task(go())

def is_owner(u): return u["id"] == ADMIN_ID or u["tg"].lstrip("@").lower() in ADMINS
def is_adm(u): return is_owner(u) or u["tg"].lstrip("@").lower() in st["admins"]

def verify(init):  # проверка подписи Telegram: без неё никто не сможет выдать себя за админа
    d = dict(parse_qsl(init, keep_blank_values=True)); h = d.pop("hash", "")
    s = "\n".join(f"{k}={v}" for k, v in sorted(d.items()))
    key = hmac.new(b"WebAppData", TOKEN.encode(), hashlib.sha256).digest()
    if not hmac.compare_digest(hmac.new(key, s.encode(), hashlib.sha256).hexdigest(), h): raise ValueError
    if time.time() - int(d["auth_date"]) > 86400: raise ValueError
    u = json.loads(d["user"]); u["tg"] = "@" + (u.get("username") or u.get("first_name") or str(u["id"]))
    return u

def pub(i, me):
    o = {k: v for k, v in i.items() if k not in ("ogid", "bc", "offers", "tf")}
    full = is_adm(me) or i["seller"] == me["id"]
    o["offers"] = [x for x in i.get("offers", []) if full or x["user"] == me["id"]]
    o["favs"] = sum(1 for l in st["favs"].values() if i["id"] in l)
    return o

async def tg_call(method, **prm):
    async with aiohttp.ClientSession() as ses:
        async with ses.post(f"https://api.telegram.org/bot{TOKEN}/{method}", json=prm) as r: return await r.json()

async def transfer(it, to_uid):  # реальная передача подарка с аккаунта-хранилища
    try:
        prm = dict(business_connection_id=it["bc"], owned_gift_id=it["ogid"], new_owner_chat_id=to_uid)
        if it.get("tf"): prm["star_count"] = it["tf"]
        r = await tg_call("transferGift", **prm)
    except Exception as e: return False, str(e)
    return bool(r.get("ok")), r.get("description", "")

async def deliver(it, to_uid):  # возврат подарка владельцу и обмены
    ok, why = await transfer(it, to_uid)
    it["delivery"] = "done" if ok else "manual"; save()
    if ok: tell(to_uid, f"Подарок {it['name']} №{it['num']} передан вам в Telegram")
    else: tell(ADMIN_ID, f"Передайте подарок вручную: {it['link']} -> {to_uid}. Ошибка: {why}")

async def settle(item_id, deal_id):  # покупка завершается ТОЛЬКО после подтверждённой передачи
    it = next((i for i in st["items"] if i["id"] == item_id), None); x = next((d for d in st["deals"] if d["id"] == deal_id), None)
    if not it or not x: return
    uid = it["buyer"]; ok, why = await transfer(it, uid)
    if ok:
        if x["held"]:
            fee = x["price"] * st["fee"] // 100; sk = str(it["seller"])
            st["bal"][sk] = st["bal"].get(sk, 0) + x["price"] - fee
            if ADMIN_ID: st["bal"][str(ADMIN_ID)] = st["bal"].get(str(ADMIN_ID), 0) + fee
            x["held"] = 0
        it["status"] = "sold"; it["delivery"] = "done"; x["step"] = 3
        x["log"].append(time.strftime("%H:%M") + " · Передача подтверждена Telegram")
        ev(f"{it['name']} №{it['num']} продан за {x['price']} ⭐")
        tell(uid, f"Подарок {it['name']} №{it['num']} передан вам"); tell(it["seller"], f"{it['name']} №{it['num']} продан за {x['price']} ⭐")
    else:
        if x["held"]: st["bal"][str(uid)] = st["bal"].get(str(uid), 0) + x["held"]
        st["deals"].remove(x); it["status"] = "live"; it.pop("buyer", None)
        tell(uid, f"Не удалось передать {it['name']}. Звёзды возвращены на баланс.")
        tell(ADMIN_ID, f"Сбой передачи {it['link']} покупателю {uid}: {why}")
    save()

def img_ok(s):
    if not s.startswith("data:image/") or len(s) > 700000: return False
    try: raw = base64.b64decode(s.split(",", 1)[1], validate=True)
    except Exception: return False
    return raw[:3] == b"\xff\xd8\xff" or raw[:8] == b"\x89PNG\r\n\x1a\n" or (raw[:4] == b"RIFF" and raw[8:12] == b"WEBP")

async def check_link(it):  # best-effort: ссылка t.me/nft/... ведёт на существующую страницу подарка. Владение этим НЕ подтверждается
    try:
        async with aiohttp.ClientSession(timeout=aiohttp.ClientTimeout(total=6)) as ses:
            async with ses.get(it["link"]) as r: html = await r.text() if r.status == 200 else ""
        it["tgcheck"] = bool(re.search(r'property="og:title"', html))
    except Exception: it["tgcheck"] = None
    save()

CATS = ("Коллекционные", "Редкие", "Сезонные", "Другое")
def lot_fields(d, cur=None):
    name = str(d.get("name", "")).strip()[:40]; link = str(d.get("link", "")).strip()
    m = re.fullmatch(r"https://t\.me/nft/([A-Za-z0-9_-]{3,60})", link)
    try: price = int(d["price"])
    except Exception: raise Err("Введите цену")
    img = str(d.get("img", "")) or (cur or {}).get("img", "")
    if not name or not m or not 1 <= price <= 1000000: raise Err("Проверьте название, ссылку t.me/nft/… и цену")
    if d.get("kind") not in ("std", "rare", "retired") or d.get("mode") not in ("sale", "deal") or d.get("backdrop") not in BDS: raise Err("Проверьте поля формы")
    if not img_ok(img): raise Err("Загрузите изображение (JPEG, PNG или WebP)")
    for i in st["items"]:
        if i.get("link") == link and i is not cur and i["status"] in ("pending", "live", "reserved", "draft", "lot", "off"): raise Err("Этот подарок уже размещён на маркете")
    tail = m.group(1).rsplit("-", 1)[-1]
    return {"name": name, "link": link, "price": price, "img": img, "num": int(tail) if tail.isdigit() else 0,
            "description": str(d.get("description", ""))[:300], "category": d.get("category") if d.get("category") in CATS else "Другое",
            "model": str(d.get("model", ""))[:30], "symbol": str(d.get("symbol", ""))[:30], "backdrop": d["backdrop"], "kind": d["kind"], "mode": d["mode"]}

def view(me):
    adm = is_adm(me); uid = me["id"]
    deals = [x for x in st["deals"] if adm or uid in (x["buyer"], x["seller"])]
    need = {x["item"] for x in deals}
    items = [pub(i, me) for i in st["items"] if adm or i["status"] in ("live", "sold") or i["seller"] == uid or i["id"] in need]
    agg = {}
    for x in st["deals"]:
        if x["step"] == 3:
            for k in (x["buyer"], x["seller"]):
                a = agg.setdefault(k, [0, 0]); a[0] += 1; a[1] += x["price"]
    top = sorted(agg.items(), key=lambda kv: (-kv[1][0], -kv[1][1]))[:10]
    return {"bot": BOTNAME, "storage": os.environ.get("STORAGE", ""),
            "top": [{"id": k, "n": v[0], "vol": v[1]} for k, v in top],
            "pay": [x for x in st["pay"] if x["uid"] == uid][-30:], "subs": st["subs"].get(str(uid), []),
            "refs": sum(1 for u in st["users"].values() if u.get("ref") == uid),
            "refLink": f"https://t.me/{BOTNAME}?start=ref_{uid}" if BOTNAME else "", "support": SUPPORT, "fee": st["fee"], "admins": st["admins"] if adm else [], "fixed": sorted(ADMINS) if adm else [], "me": {"id": uid, "tg": me["tg"], "admin": adm, "owner": is_owner(me), "stars": st["bal"].get(str(uid), 0)},
            "users": [{"id": u["id"], "tg": u["tg"], "blocked": u["blocked"], "ver": u.get("ver", False), "dn": agg.get(u["id"], [0, 0])[0]} for u in st["users"].values()],
            "items": items, "ev": st["ev"][-8:], "swaps": [x for x in st["swaps"] if adm or me["id"] in (x["from"], x["to"])], "favs": st["favs"].get(str(uid), []), "deals": deals,
            "media": [m for m in st["media"] if adm or m["user"] == uid],
            "tickets": st["tickets"] if adm else []}

def announce(it):  # уведомление подписчикам коллекции о новом лоте
    for k, l in st["subs"].items():
        if it["name"] in l and int(k) != it["seller"]: tell(int(k), f"Новый лот в «{it['name']}»: №{it['num']} за {it['price']} ⭐")

def ev(text):
    st["ev"].append({"t": int(time.time()), "x": text}); del st["ev"][:-20]

def setp(it, pr):  # смена цены: история + уведомление тем, у кого подарок в избранном
    old = it.get("price", 0)
    if old and pr < old:
        for k, l in st["favs"].items():
            if it["id"] in l and int(k) != it["seller"]: tell(int(k), f"Цена снижена: {it['name']} №{it['num']}: {old} → {pr} ⭐")
    it["price"] = pr; it.setdefault("ph", []).append([int(time.time()), pr]); del it["ph"][:-30]

def run(me, op, d):
    uid, adm, now = me["id"], is_adm(me), time.strftime("%H:%M")
    if me["blocked"] and op != "state": raise Err("Аккаунт заблокирован")
    def need_adm():
        if not adm: raise Err("Только для администраторов")
    def find(lst, k="id"):
        x = next((x for x in lst if x["id"] == d.get(k)), None)
        if not x: raise Err("Не найдено")
        return x
    def log(x, t): x["log"].append(f"{now} · {t}")
    if op == "state": return
    if op == "fav":
        l = st["favs"].setdefault(str(uid), []); i = d.get("id")
        l.remove(i) if i in l else l.append(i)
    elif op == "new_item":
        if sum(1 for i in st["items"] if i["seller"] == uid and i["status"] == "pending") >= 5: raise Err("Слишком много лотов на модерации")
        f = lot_fields(d); n = st["nid"]; st["nid"] += 1
        it = {"id": n, **f, "seller": uid, "status": "live" if adm else "pending", "hue": n, "date": n, "custody": False,
              "bargain": False, "offers": [], "appr": adm}
        st["items"].append(it); asyncio.get_running_loop().create_task(check_link(it))
        if not adm: tell(ADMIN_ID, f"Новый лот на модерации (не проверен): {f['name']}, {f['price']} ⭐ {f['link']}")
    elif op == "item_edit":
        it = find(st["items"])
        if it["seller"] != uid or it["status"] in ("reserved", "sold", "out"): raise Err("Нельзя изменить")
        if it.get("custody"):
            it["description"] = str(d.get("description", ""))[:300]; it["category"] = d.get("category") if d.get("category") in CATS else "Другое"
        else:
            f = lot_fields(d, it); keys = ("name", "link", "img", "model", "symbol", "backdrop", "kind", "mode", "description", "category")
            changed = any(it.get(k) != f[k] for k in keys)
            if f["price"] != it["price"]: setp(it, f["price"])
            if f["link"] != it["link"]: asyncio.get_running_loop().create_task(check_link(it))
            it.update({k: f[k] for k in keys}); it["num"] = f["num"]
            if changed and not adm and it["status"] in ("live", "rej"): it["status"] = "pending"; it["appr"] = False
    elif op == "item_relist":
        it = find(st["items"])
        if it["seller"] != uid or it.get("custody") or it["status"] != "off": raise Err("Нельзя выставить")
        it["status"] = "live" if (it.get("appr") or adm) else "pending"
    elif op == "buy":
        it = find(st["items"])
        if it["status"] not in ("live", "lot") or it["seller"] == uid or it.get("custody"): raise Err("Подарок недоступен")
        if it.get("for") and it["for"] != uid: raise Err("Цена согласована с другим покупателем")
        if any(x["item"] == it["id"] and x["step"] < 3 and x["buyer"] == uid for x in st["deals"]): raise Err("Сделка уже создана")
        n = st["nid"]; st["nid"] += 1
        x = {"id": n, "item": it["id"], "buyer": uid, "seller": it["seller"], "step": 0, "log": [], "dispute": False,
             "price": it["price"], "pc": False, "g": None, "gs": False, "gg": False, "held": 0}
        log(x, f"Сделка создана. Цена для покупателя: {it['price']} ⭐"); st["deals"].append(x)
        tell(it["seller"], f"{me['tg']} хочет купить {it['name']} №{it['num']}. Гарант скоро подключится.")
        tell(ADMIN_ID, f"Новая сделка #{n}: нужен гарант")
    elif op == "cancel":
        x = find(st["deals"])
        if uid not in (x["buyer"], x["seller"]) and not adm: raise Err("Нет доступа")
        if x["step"] >= 3 or (x["g"] and not adm): raise Err("Сделку ведёт гарант")
        if x["held"]: st["bal"][str(x["buyer"])] = st["bal"].get(str(x["buyer"]), 0) + x["held"]
        st["deals"].remove(x)
    elif op == "ticket":
        text = str(d.get("text", "")).strip()[:500]
        if not text: raise Err("Опишите проблему")
        if d.get("deal"):
            x = find(st["deals"], "deal")
            if uid in (x["buyer"], x["seller"]) or adm: x["dispute"] = True; log(x, "Обращение в поддержку")
            text = f"[Сделка #{x['id']}] " + text
        n = st["nid"]; st["nid"] += 1
        st["tickets"].append({"id": n, "from": me["tg"], "text": text, "done": False}); tell(ADMIN_ID, f"Обращение от {me['tg']}: {text}")
    elif op == "media_apply":
        link, tg = str(d.get("link", ""))[:200], str(d.get("tg", ""))[:40]
        try: k = int(d["n"])
        except Exception: raise Err("Укажите число видео")
        if not link or not tg or k <= 0: raise Err("Заполните все поля")
        n = st["nid"]; st["nid"] += 1
        st["media"].append({"id": n, "user": uid, "link": link, "tg": tg, "n": k, "s": "new"}); tell(ADMIN_ID, f"Заявка в Media: {tg}")
    elif op == "block":
        need_adm(); u = st["users"].get(str(d.get("id")))
        if not u or is_adm(u): raise Err("Нельзя")
        u["blocked"] = not u["blocked"]
    elif op == "sub":
        nm = str(d.get("name", ""))[:60]
        if not nm: raise Err("Нет названия")
        l = st["subs"].setdefault(str(uid), [])
        l.remove(nm) if nm in l else l.append(nm)
    elif op == "verify":
        need_adm(); u = st["users"].get(str(d.get("id")))
        if not u: raise Err("Нет пользователя")
        u["ver"] = not u.get("ver", False)
    elif op == "moderate":
        need_adm(); it = find(st["items"])
        if d.get("status") not in ("live", "rej"): raise Err("Неверный статус")
        it["status"] = d["status"]; it["appr"] = d["status"] == "live"; announce(it) if d["status"] == "live" else None; tell(it["seller"], f"{it['name']} №{it['num']}: " + ("опубликовано" if d["status"] == "live" else "отклонено"))
    elif op == "media_decide":
        need_adm(); m = find(st["media"])
        if d.get("s") not in ("ok", "no"): raise Err("Неверный статус")
        m["s"] = d["s"]; tell(m["user"], "Заявка в GIFTORA Media: " + ("принята" if d["s"] == "ok" else "отклонена"))
    elif op == "ticket_close": need_adm(); find(st["tickets"])["done"] = True
    elif op == "price_confirm":
        need_adm(); x = find(st["deals"]); x["pc"] = not x["pc"]
        log(x, f"Администратор подтвердил цену: {x['price']} ⭐" if x["pc"] else "Подтверждение цены снято")
    elif op in ("gt", "gs", "gg", "gd"):
        need_adm(); x = find(st["deals"])
        if x["step"] >= 3: raise Err("Сделка завершена")
        if op == "gt":
            if x["g"] or uid in (x["buyer"], x["seller"]): raise Err("Гарантом стать нельзя")
            x["g"] = me["tg"]; log(x, f"Гарант {me['tg']} проводит сделку: звёзды и подарок передаются гаранту")
            tell(x["buyer"], f"Сделка #{x['id']}: гарант {me['tg']}. Передайте звёзды гаранту.")
            tell(x["seller"], f"Сделка #{x['id']}: гарант {me['tg']}. Передайте подарок гаранту.")
        elif x["g"] != me["tg"]: raise Err("Вы не гарант этой сделки")
        elif op == "gs" and not x["gs"]:
            b = st["users"].get(str(x["buyer"]), {"id": x["buyer"], "tg": ""})
            if not is_adm(b):  # у админов звёзды не списываются
                if st["bal"].get(str(x["buyer"]), 0) < x["price"]: raise Err("У покупателя недостаточно звёзд")
                st["bal"][str(x["buyer"])] -= x["price"]; x["held"] = x["price"]
            x["gs"] = True; x["step"] = max(x["step"], 1); log(x, "Гарант получил звёзды")
        elif op == "gg" and not x["gg"]: x["gg"] = True; x["step"] = max(x["step"], 2); log(x, "Гарант получил подарок")
        elif op == "gd":
            if not (x["gs"] and x["gg"]): raise Err("Нужны звёзды и подарок")
            if x["held"]:
                fee = x["held"] * st["fee"] // 100
                st["bal"][str(x["seller"])] = st["bal"].get(str(x["seller"]), 0) + x["held"] - fee
                if ADMIN_ID: st["bal"][str(ADMIN_ID)] = st["bal"].get(str(ADMIN_ID), 0) + fee
                x["held"] = 0
            x["step"] = 3;
            next(i for i in st["items"] if i["id"] == x["item"])["status"] = "sold"
            log(x, "Гарант передал подарок покупателю и звёзды продавцу")
            tell(x["buyer"], f"Сделка #{x['id']} завершена"); tell(x["seller"], f"Сделка #{x['id']} завершена, звёзды зачислены")
    elif op in ("admin_add", "admin_del", "set_fee"):
        if not is_owner(me): raise Err("Только владелец")
        if op == "set_fee":
            try: f = int(d["fee"])
            except Exception: raise Err("Введите число")
            if not 0 <= f <= 30: raise Err("От 0 до 30")
            st["fee"] = f
        else:
            t = str(d.get("tg", "")).strip().lstrip("@").lower()
            if not re.fullmatch(r"[a-z0-9_]{5,32}", t): raise Err("Неверный username")
            if op == "admin_add" and t not in st["admins"]: st["admins"].append(t)
            if op == "admin_del" and t in st["admins"]: st["admins"].remove(t)
    elif op in ("item_price", "item_remove"):
        it = find(st["items"])
        if it["seller"] != uid and not adm: raise Err("Нет доступа")
        if it["status"] not in ("live", "pending") or any(x["item"] == it["id"] and x["step"] < 3 for x in st["deals"]):
            raise Err("Сейчас нельзя изменить: по подарку идёт сделка")
        if op == "item_remove": it["status"] = "draft" if it.get("custody") else "off"
        else:
            try: pr = int(d["price"])
            except Exception: raise Err("Введите цену")
            if pr <= 0: raise Err("Цена должна быть больше нуля")
            setp(it, pr)
    elif op == "withdraw":
        try: a = int(d["amount"])
        except Exception: raise Err("Введите число")
        if a <= 0 or a > st["bal"].get(str(uid), 0): raise Err("Недостаточно звёзд")
        st["bal"][str(uid)] -= a; n = st["nid"]; st["nid"] += 1
        st["tickets"].append({"id": n, "from": me["tg"], "text": f"Вывод {a} ⭐", "done": False})
        tell(ADMIN_ID, f"Заявка на вывод: {me['tg']} {a} ⭐")
    elif op == "list_item":
        it = find(st["items"])
        if it["seller"] != uid or not it.get("custody") or it["status"] not in ("draft", "live"): raise Err("Нельзя выставить")
        try: pr = int(d["price"])
        except Exception: raise Err("Введите цену")
        if not 1 <= pr <= 1000000: raise Err("Цена от 1 до 1 000 000")
        was = it["status"]; setp(it, pr); it["bargain"] = bool(d.get("bargain")); it["status"] = "live"; it["for"] = None
        ev(f"{it['name']} №{it['num']} выставлен за {pr} ⭐")
        if was != "live": announce(it)
    elif op == "unlist":
        it = find(st["items"])
        if it["seller"] != uid or not it.get("custody") or it["status"] != "live": raise Err("Нельзя снять")
        it["status"] = "draft"
    elif op == "gift_out":
        it = find(st["items"])
        if it["seller"] != uid or not it.get("custody") or it["status"] != "draft": raise Err("Нельзя вернуть")
        it["status"] = "out"; asyncio.get_running_loop().create_task(deliver(it, uid))
    elif op == "buy_now":
        it = find(st["items"])
        if it["status"] != "live" or not it.get("custody") or it["seller"] == uid: raise Err("Подарок недоступен")
        if it.get("for") and it["for"] != uid: raise Err("Цена согласована с другим покупателем")
        price = it["price"]; paid = False
        if not adm:
            if st["bal"].get(str(uid), 0) < price: raise Err("Недостаточно звёзд. Пополните баланс")
            st["bal"][str(uid)] -= price; paid = True
        it["status"] = "reserved"; it["buyer"] = uid; n = st["nid"]; st["nid"] += 1
        st["deals"].append({"id": n, "item": it["id"], "buyer": uid, "seller": it["seller"], "step": 2,
                            "log": [f"{now} · Звёзды получены, подарок передаётся"], "dispute": False, "price": price,
                            "pc": True, "g": "GIFTORA", "gs": True, "gg": True, "held": price if paid else 0})
        asyncio.get_running_loop().create_task(settle(it["id"], n))
    elif op == "lot_new":
        link = str(d.get("link", "")).strip(); name = str(d.get("name", "")).strip()[:40]
        m = re.fullmatch(r"https://t\.me/nft/([A-Za-z0-9_-]{3,60})", link)
        try: pr = int(d["price"])
        except Exception: raise Err("Введите цену")
        if not name or not m or not 1 <= pr <= 1000000: raise Err("Проверьте название, ссылку t.me/nft/… и цену")
        while True:
            code = "G-" + "".join(random.choices("ABCDEFGHJKLMNPQRSTUVWXYZ23456789", k=6))
            if not any(i.get("code") == code for i in st["items"]): break
        tail = m.group(1).rsplit("-", 1)[-1]; n = st["nid"]; st["nid"] += 1
        st["items"].append({"id": n, "name": name, "num": int(tail) if tail.isdigit() else 0, "price": pr, "kind": "std",
                            "mode": "deal", "img": "", "seller": uid, "status": "lot", "hue": n, "date": n, "link": link,
                            "model": "", "symbol": "", "backdrop": "", "code": code, "bargain": bool(d.get("bargain")),
                            "offers": [], "for": None})
        d["_res"] = code
    elif op == "lot_find":
        code = str(d.get("code", "")).strip().upper()
        it = next((i for i in st["items"] if i.get("code") == code and i["status"] == "lot"), None)
        if not it: raise Err("Сделка с таким номером не найдена")
        d["_res"] = pub(it, me)
    elif op == "lot_offer":
        it = find(st["items"])
        try: pr = int(d["price"])
        except Exception: raise Err("Введите цену")
        if it["status"] not in ("lot", "live") or not it.get("bargain") or it["seller"] == uid or not 1 <= pr < it["price"]:
            raise Err("Торг недоступен или цена неверна")
        if any(o["user"] == uid and o["s"] == "new" for o in it["offers"]): raise Err("Ваше предложение уже отправлено")
        n = st["nid"]; st["nid"] += 1
        it["offers"].append({"id": n, "user": uid, "tg": me["tg"], "price": pr, "s": "new"})
        tell(it["seller"], f"{me['tg']} предлагает {pr} ⭐ за {it['name']} (запрошено {it['price']} ⭐)")
    elif op == "lot_accept":
        it = find(st["items"])
        if it["seller"] != uid: raise Err("Нет доступа")
        o = next((o for o in it["offers"] if o["id"] == d.get("oid")), None)
        if not o or o["s"] != "new": raise Err("Предложение не найдено")
        if d.get("ok"):
            o["s"] = "ok"; it["price"] = o["price"]; it["for"] = o["user"]
            tell(o["user"], f"Ваша цена {o['price']} ⭐ принята. " + (f"Найдите сделку по номеру {it['code']} и оплатите." if it.get("code") else "Откройте подарок в GIFTORA и купите."))
        else: o["s"] = "no"
    elif op == "lot_close":
        it = find(st["items"])
        if (it["seller"] != uid and not adm) or it["status"] != "lot": raise Err("Нельзя закрыть")
        it["status"] = "rej"
    elif op == "swap_offer":
        a, b = find(st["items"], "mine"), find(st["items"], "want")
        if a["seller"] != uid or not a.get("custody") or a["status"] not in ("draft", "live"): raise Err("Ваш подарок должен быть на хранении")
        if not b.get("custody") or b["status"] != "live" or b["seller"] == uid: raise Err("Этот подарок недоступен для обмена")
        try: ex = int(d.get("extra") or 0)
        except Exception: raise Err("Неверная доплата")
        if not 0 <= ex <= 1000000: raise Err("Неверная доплата")
        n = st["nid"]; st["nid"] += 1
        st["swaps"].append({"id": n, "from": uid, "to": b["seller"], "mine": a["id"], "want": b["id"], "extra": ex, "s": "new", "t": int(time.time())})
        tell(b["seller"], f"{me['tg']} предлагает обмен: {a['name']} №{a['num']} на {b['name']} №{b['num']}" + (f" + {ex} ⭐" if ex else ""))
    elif op in ("swap_answer", "swap_cancel"):
        x = find(st["swaps"])
        if x["s"] != "new": raise Err("Предложение уже закрыто")
        if op == "swap_cancel":
            if x["from"] != uid: raise Err("Нет доступа")
            x["s"] = "cancel"
        elif x["to"] != uid: raise Err("Нет доступа")
        elif not d.get("ok"): x["s"] = "no"; tell(x["from"], "Предложение обмена отклонено")
        else:
            a = next(i for i in st["items"] if i["id"] == x["mine"]); b = next(i for i in st["items"] if i["id"] == x["want"])
            if a["status"] not in ("draft", "live") or b["status"] != "live" or a["seller"] != x["from"] or b["seller"] != uid:
                raise Err("Один из подарков уже недоступен")
            pk, sk = str(x["from"]), str(uid)
            if x["extra"]:
                if st["bal"].get(pk, 0) < x["extra"]: raise Err("У предложившего недостаточно звёзд для доплаты")
                fee = x["extra"] * st["fee"] // 100
                st["bal"][pk] -= x["extra"]; st["bal"][sk] = st["bal"].get(sk, 0) + x["extra"] - fee
                if ADMIN_ID: st["bal"][str(ADMIN_ID)] = st["bal"].get(str(ADMIN_ID), 0) + fee
            a["status"] = "sold"; b["status"] = "sold"; x["s"] = "ok"
            loop = asyncio.get_running_loop(); loop.create_task(deliver(a, uid)); loop.create_task(deliver(b, x["from"]))
            tell(x["from"], f"Обмен принят: {b['name']} №{b['num']} отправляется вам"); ev(f"Обмен: {a['name']} ⇄ {b['name']}")
    else: raise Err("Неизвестное действие")

async def api(req):
    try:
        me = verify(req.headers.get("X-Init-Data", ""))
        j = await req.json()
        u = st["users"].setdefault(str(me["id"]), {"id": me["id"], "tg": me["tg"], "blocked": False}); u["tg"] = me["tg"]
        data = j.get("data") or {}
        run(u, j.get("op"), data); save()
        return web.json_response({"state": view(u), "result": data.get("_res")})
    except Err as e: return web.json_response({"error": str(e)}, status=400)
    except Exception: return web.json_response({"error": "Откройте приложение через бота в Telegram"}, status=401)

WELCOME = ("<b>GIFTORA</b> — маркетплейс Telegram NFT Gifts.\n\nПокупайте, продавайте, обменивайте и коллекционируйте подарки. "
           "Мгновенная покупка за звёзды, обмены между коллекционерами и безопасные сделки через гаранта.")
HELP = ("Как это работает:\n• Продать: передайте NFT-подарок на аккаунт-хранилище и выставьте его в приложении.\n"
        "• Купить: нажмите «Купить сейчас», звёзды спишутся с баланса, подарок придёт вам.\n"
        "• Обменять: предложите обмен своего подарка на чужой.\n• Пополнить баланс: Профиль → Пополнить (Telegram Stars).")
FILE_ID = None

def start_kb():
    rows = [[InlineKeyboardButton(text="🎁 Открыть GIFTORA", web_app=WebAppInfo(url=URL))]]
    if CHANNEL: rows.append([InlineKeyboardButton(text="📢 Telegram-канал", url=CHANNEL)])
    rows.append([InlineKeyboardButton(text="❓ Помощь", callback_data="help")])
    return InlineKeyboardMarkup(inline_keyboard=rows)

@dp.message(Command("start"))
async def start(m: Message):
    global FILE_ID
    p = (m.text or "").split(maxsplit=1)
    if len(p) > 1 and p[1].startswith("topup_"):   # запасной путь пополнения через чат
        try: n = int(p[1][6:])
        except ValueError: return
        if 1 <= n <= 10000:
            await m.answer_invoice(title="Пополнение GIFTORA", description=f"{n} звёзд на баланс", payload=f"topup:{m.from_user.id}:{n}",
                                   currency="XTR", prices=[LabeledPrice(label="Звёзды", amount=n)])
        return
    if len(p) > 1 and p[1].startswith("ref_") and m.from_user and str(m.from_user.id) not in st["users"]:
        try: r = int(p[1][4:])
        except ValueError: r = 0
        if r and r != m.from_user.id and str(r) in st["users"]:
            st["users"][str(m.from_user.id)] = {"id": m.from_user.id, "blocked": False, "ref": r,
                                                 "tg": "@" + (m.from_user.username or m.from_user.first_name or str(m.from_user.id))}
            save()
    try:
        photo = FILE_ID or BufferedInputFile(BANNER, "giftora.jpg")
        msg = await m.answer_photo(photo, caption=WELCOME, reply_markup=start_kb(), parse_mode="HTML")
        if not FILE_ID and msg.photo: FILE_ID = msg.photo[-1].file_id
    except Exception:
        await m.answer(WELCOME, reply_markup=start_kb(), parse_mode="HTML")

@dp.callback_query(F.data == "help")
async def help_cb(q: CallbackQuery):
    await q.message.answer(HELP + (f"\n\nПоддержка: {SUPPORT}" if SUPPORT else "")); await q.answer()

@dp.business_message()
async def biz(m: Message):  # подарок, переданный на аккаунт-хранилище, автоматически попадает на маркет
    raw = m.model_dump(mode="json", exclude_none=True); ug = raw.get("unique_gift")
    if not ug or not m.from_user: return
    g, uid, ogid = ug["gift"], m.from_user.id, ug.get("owned_gift_id")
    if ogid and any(i.get("ogid") == ogid for i in st["items"]): return
    u = st["users"].setdefault(str(uid), {"id": uid, "tg": "", "blocked": False})
    u["tg"] = "@" + (m.from_user.username or m.from_user.first_name or str(uid))
    col = g.get("backdrop", {}).get("colors", {}); hx = lambda c: "#%06x" % int(c or 0)
    n = st["nid"]; st["nid"] += 1
    st["items"].append({"id": n, "name": g.get("base_name", g["name"]), "num": g.get("number", 0), "price": 0, "kind": "std",
                        "mode": "sale", "img": "", "seller": uid, "status": "draft", "hue": n, "date": n,
                        "link": f"https://t.me/nft/{g['name']}", "model": g.get("model", {}).get("name", ""),
                        "symbol": g.get("symbol", {}).get("name", ""), "backdrop": g.get("backdrop", {}).get("name", ""),
                        "bgc": [hx(col.get("center_color")), hx(col.get("edge_color"))], "custody": True, "rar": g.get("model", {}).get("rarity_per_mille"), "ogid": ogid,
                        "bc": m.business_connection_id, "tf": ug.get("transfer_star_count", 0), "bargain": False,
                        "offers": [], "delivery": ""})
    save()
    tell(uid, f"Подарок {g.get('base_name', g['name'])} №{g.get('number', '')} получен. Откройте GIFTORA → Профиль → Мои подарки и выставите цену.")

@dp.pre_checkout_query()
async def pre(q: PreCheckoutQuery): await q.answer(ok=True)

@dp.message(F.successful_payment)
async def paid(m: Message):  # баланс пополняется только после подтверждения платежа Telegram
    sp = m.successful_payment; k = str(m.from_user.id)
    if sp.currency != "XTR" or not sp.invoice_payload.startswith("topup"): return
    cid = sp.telegram_payment_charge_id
    if any(x["id"] == cid for x in st["pay"]): return
    n = sp.total_amount; st["bal"][k] = st["bal"].get(k, 0) + n
    st["pay"].append({"id": cid, "uid": m.from_user.id, "amount": n, "t": int(time.time())}); save()
    await m.answer(f"Баланс пополнен на {n} ⭐. Сейчас: {st['bal'][k]} ⭐")
    tell(ADMIN_ID, f"Пополнение: @{m.from_user.username} +{n} ⭐")

async def invoice(req):
    try:
        me = verify(req.headers.get("X-Init-Data", "")); n = int((await req.json())["amount"])
    except Exception: return web.json_response({"error": "Откройте приложение через бота в Telegram"}, status=401)
    u = st["users"].get(str(me["id"]))
    if (u and u["blocked"]) or not 1 <= n <= 10000: return web.json_response({"error": "Неверная сумма"}, status=400)
    try:
        link = await bot.create_invoice_link(title="Пополнение GIFTORA", description=f"{n} звёзд на баланс",
                                             payload=f"topup:{me['id']}:{n}", currency="XTR", prices=[LabeledPrice(label="Звёзды", amount=n)])
    except Exception: return web.json_response({"error": "Не удалось создать счёт"}, status=502)
    return web.json_response({"link": link})

async def main():
    global BOTNAME
    BOTNAME = (await bot.me()).username
    for i in st["items"]:
        if i["status"] == "reserved": tell(ADMIN_ID, f"Покупка зависла после перезапуска: {i['name']} №{i['num']}, покупатель {i.get('buyer')}. Проверьте передачу вручную.")
    print("START: ADMIN_ID =", ADMIN_ID, "| ADMINS =", sorted(ADMINS), "| WEBAPP_URL =", URL, flush=True)
    try: await bot.set_chat_menu_button(menu_button=MenuButtonWebApp(text="GIFTORA", web_app=WebAppInfo(url=URL)))
    except Exception: pass
    app = web.Application(client_max_size=2 * 1024 * 1024)
    here = os.path.dirname(os.path.abspath(__file__))
    app.add_routes([web.get("/", lambda r: web.Response(text=PAGE, content_type="text/html", headers={"Cache-Control": "no-store"})),
                    web.get("/health", lambda r: web.Response(text="ok")), web.post("/api/op", api), web.post("/api/invoice", invoice),
                    web.get("/{tail:.*}", lambda r: web.Response(text=PAGE, content_type="text/html", headers={"Cache-Control": "no-store"}))])
    runner = web.AppRunner(app); await runner.setup()
    await web.TCPSite(runner, "0.0.0.0", int(os.environ.get("PORT", "8080"))).start()
    await dp.start_polling(bot)

if __name__ == "__main__": asyncio.run(main())
